    assert.equal(res.status, 400, url);
    assert.equal(healCalls.length, 0, `${url} reached the heal API without a model`);
  }
});

// The Responses API lets the model live on a stored prompt template instead of
// in the body. Those calls are ordinary Responses traffic and fail the same way,
// so the dialect claims `prompt` as a second identifying key.
test('a stored-prompt Responses call with no model heals like any other', async () => {
  const stub = providerStub([err400('bad knob'), ok200]);
  const res = await autofix({ fetch: stub.fn })('https://api.openai.com/v1/responses',
    aiSdkInit({ prompt: { id: 'pmpt_abc', version: '2' }, temperature: 0.2 }, 'openai'));
  assert.equal(res.status, 200, 'healed and replayed');
  assert.equal(healCalls[0]!.body!.api, 'responses');
});

test('prompt does not identify the dialects that never accept it', async () => {
  for (const url of [
    'https://api.openai.com/v1/chat/completions',
    'https://api.anthropic.com/v1/messages',
  ]) {
    healCalls = [];
    const stub = providerStub([err400('nope')]);
    const res = await autofix({ fetch: stub.fn })(url,
      aiSdkInit({ prompt: { id: 'pmpt_abc' } }, 'openai'));
    assert.equal(res.status, 400, url);
    assert.equal(healCalls.length, 0, `${url} opened on a key it does not own`);
  }
});

// Without an attempt id there is no outcome report to hand the failed replay
// to, and nobody else ever reads it: under undici that body pins a pooled
// connection until GC, on every healed failure a server answers this way.
test('a failed replay is drained when the heal API sends no healAttemptId', async () => {
  let cancelled = false;
  globalThis.fetch = (async (_input: never, init?: RequestInit) => {
    healCalls.push({ method: init?.method ?? 'GET', body: undefined, headers: {} });
    return new Response(JSON.stringify({
      status: 'patched', issueId: 'i1', healedBody: { model: 'm2' }, // no healAttemptId
    }), { status: 200 });
  }) as typeof globalThis.fetch;

  let call = 0;
  const provider = (async () => {
    call += 1;
    if (call === 1) return err400('bad knob')();
    return new Response(new ReadableStream({
      start: (c) => { c.enqueue(new TextEncoder().encode('{"error":{"message":"still bad"}}')); },
      // Releasing an already-broken connection can reject; an unhandled
      // rejection would land during the wait below.
      cancel: () => { cancelled = true; throw new Error('already gone'); },
    }), { status: 400 });
  }) as typeof globalThis.fetch;

  const res = await autofix({ fetch: provider })('https://api.openai.com/v1/chat/completions',
    aiSdkInit({ model: 'm', max_tokens: 10 }, 'openai'));
  assert.equal(res.status, 400, 'the caller keeps their own error');
  await new Promise((r) => setTimeout(r, 20));
  assert.equal(cancelled, true, 'the failed replay body was left pinning a connection');
  assert.deepEqual(healCalls.map((c) => c.method), ['POST'], 'no attempt id, so no PATCH');
});

test('official-SDK traffic through the root export classifies per SDK', async () => {
  const stub = providerStub([err400('bad'), ok200]);
  await autofix({ fetch: stub.fn })('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: { 'user-agent': 'Anthropic/JS 0.115.0', 'x-api-key': 'sk-ant' },
    body: JSON.stringify({ model: 'claude-opus-4-6', max_tokens: 10 }),
  });
  assert.equal(healCalls[0]!.headers['x-autofix-source'], 'anthropic-sdk');
});

"""Native Google Gemini GenerateContent transport behavior."""

import json

import httpx

from mnfst_autofix.google import AutofixTransport, detect

HEAL_URL = "http://heal.test"
ERR_404 = (404, {"error": {
    "code": 404, "message": "models/gemini-1.0-pro is not found", "status": "NOT_FOUND",
}})
OK_200 = (200, {"candidates": []})


class ProviderStub:
    def __init__(self, script):
        self.script = script
        self.calls = []

    def handler(self, request):
        self.calls.append({"url": str(request.url), "body": json.loads(request.content)})
        status, body = self.script[min(len(self.calls) - 1, len(self.script) - 1)]
        return httpx.Response(status, json=body)

    def transport(self):
        return httpx.MockTransport(self.handler)


class HealStub:
    def __init__(self, healed_body):
        self.healed_body = healed_body
        self.calls = []

    def handler(self, request):
        body = json.loads(request.content) if request.content else None
        self.calls.append({"method": request.method, "body": body})
        return httpx.Response(200, json={
            "status": "unverified", "issueId": "i1", "healAttemptId": "a1",
            "healedBody": self.healed_body,
        })

    def client(self):
        return httpx.Client(transport=httpx.MockTransport(self.handler))


def client(provider, heal, **options):
    return httpx.Client(transport=AutofixTransport(
        detect, inner=provider.transport(), heal_client=heal.client(), **options,
    ))


def post(client_, url, body):
    return client_.post(url, content=json.dumps(body), headers={"x-goog-api-key": "secret"})


def test_heals_generate_content_and_includes_contents_when_opted_in(monkeypatch):
    monkeypatch.setenv("AUTOFIX_URL", HEAL_URL)
    provider = ProviderStub([ERR_404, OK_200])
    heal = HealStub({"model": "models/gemini-2.5-flash",
                     "generationConfig": {"temperature": 1}})
    body = {
        "contents": [{"role": "user", "parts": [{"text": "private prompt"}]}],
        "generationConfig": {"temperature": 0.2},
    }
    url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.0-pro:generateContent"

    response = post(client(provider, heal, send_messages=True), url, body)

    assert response.status_code == 200
    payload = heal.calls[0]["body"]
    assert payload["provider"] == "gemini"
    assert payload["api"] == "chat_completions"
    assert payload["response"]["error"] == {
        "message": "models/gemini-1.0-pro is not found", "type": "NOT_FOUND", "code": "404",
    }
    assert payload["request"] == {"model": "gemini-1.0-pro", **body}
    exchange = payload["providerExchange"]
    assert exchange["format"] == "google_generate_content"
    assert exchange["request"]["body"] == body
    assert "redactedFields" not in exchange["request"]
    assert provider.calls[1]["url"].endswith("/models/gemini-2.5-flash:generateContent")
    assert "model" not in provider.calls[1]["body"]
    assert provider.calls[1]["body"]["contents"] == body["contents"]


def test_stream_path_redacts_content_and_preserves_query(monkeypatch):
    monkeypatch.setenv("AUTOFIX_URL", HEAL_URL)
    provider = ProviderStub([ERR_404, OK_200])
    heal = HealStub({"model": "gemini-2.5-flash", "generationConfig": {"temperature": 1}})
    body = {
        "contents": [{"role": "user", "parts": [{"text": "private prompt"}]}],
        "systemInstruction": {"parts": [{"text": "private system"}]},
        "generationConfig": {"temperature": 0.2},
    }
    url = "https://gateway.test/v1beta/models/gemini-1.0-pro:streamGenerateContent?alt=sse"

    response = post(client(provider, heal), url, body)

    assert response.status_code == 200
    payload = heal.calls[0]["body"]
    assert payload["url"].endswith("gemini-1.0-pro:streamGenerateContent")
    assert "?alt=sse" not in payload["url"]
    assert payload["providerExchange"]["request"]["redactedFields"] == [
        "contents", "systemInstruction",
    ]
    assert provider.calls[1]["url"].endswith("streamGenerateContent?alt=sse")
    assert provider.calls[1]["body"]["contents"] == body["contents"]


def test_non_google_paths_and_model_less_routes_are_safe():
    assert detect(httpx.URL("https://gateway.test/v1/messages")) is None
    url = httpx.URL("https://gateway.test/v1beta/gemini:generateContent")
    route = detect(url)
    assert route is not None
    assert route.model is None
    assert route.replay is not None
    replay_url, replay_body = route.replay(url, {"model": "gemini-2.5-flash", "contents": []})
    assert replay_url == url
    assert replay_body == {"contents": []}

"""Twin of node/tests/anonymize.test.ts.

The privacy boundary is stated once, in ../../tests/anonymize-cases.json, and
run here and in Node. Twin packages that agree because they read the same table,
not because someone compared them by eye.
"""

import copy
import json
import pathlib

import pytest

from mnfst_autofix.core.anonymize import merge_healed_body, strip_request

CASES = json.loads(
    (pathlib.Path(__file__).resolve().parents[2] / "tests" / "anonymize-cases.json").read_text()
)


@pytest.mark.parametrize("case", CASES["strip"], ids=lambda c: c["name"])
def test_strip(case):
    assert strip_request(case["request"]) == case["sent"]


@pytest.mark.parametrize("case", CASES["strip_send_messages"], ids=lambda c: c["name"])
def test_strip_send_messages(case):
    assert strip_request(case["request"], send_messages=True) == case["sent"]


@pytest.mark.parametrize("case", CASES["merge"], ids=lambda c: c["name"])
def test_merge(case):
    assert merge_healed_body(case["request"], case["healed"]) == case["replay"]


def test_nothing_marked_secret_survives_the_strip_in_any_case_in_the_table():
    """Whatever the table says, no secret is allowed to appear anywhere in the
    bytes that actually go out - a nesting the table's own expectations got
    wrong would still be caught here."""
    for case in CASES["strip"]:
        wire = json.dumps(strip_request(case["request"]))
        for secret in ("SECRET", "THE USERS WHOLE DOCUMENT", "acme-42", "user-99",
                       "sid-1", "cache-1", "MCP_BEARER"):
            assert secret not in wire, f"{case['name']}: {secret}"


def test_strip_request_copies_the_callers_own_request_is_never_touched():
    original = {
        "model": "m",
        "thinking": {"type": "enabled", "budget_tokens": 8000},
        "modalities": ["text"],
    }
    stripped = strip_request(original)
    stripped["thinking"]["budget_tokens"] = 1
    stripped["modalities"].append("audio")
    assert original["thinking"] == {"type": "enabled", "budget_tokens": 8000}
    assert original["modalities"] == ["text"]


def test_merge_healed_body_mutates_neither_argument():
    original = {"model": "a", "messages": ["m"], "thinking": {"type": "enabled"}}
    healed = {"model": "b", "thinking": {"type": "disabled"}}
    before = copy.deepcopy((original, healed))
    merge_healed_body(original, healed)
    assert (original, healed) == before

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { mergeHealedBody, stripRequest } from '../src/core/anonymize.ts';

// The privacy boundary is stated once, in ../../tests/anonymize-cases.json, and
// run here and in python/tests/test_anonymize.py. Twin packages that agree
// because they read the same table, not because someone compared them by eye.
interface Case {
  name: string;
  request: Record<string, unknown>;
  sent?: Record<string, unknown>;
  healed?: Record<string, unknown>;
  replay?: Record<string, unknown>;
}
const cases = JSON.parse(
  readFileSync(new URL('../../tests/anonymize-cases.json', import.meta.url), 'utf8'),
) as { strip: Case[]; strip_send_messages: Case[]; merge: Required<Case>[] };

for (const c of cases.strip) {
  test(`strip: ${c.name}`, () => {
    assert.deepEqual(stripRequest(c.request), c.sent);
  });
}

for (const c of cases.strip_send_messages) {
  test(`strip with sendMessages: ${c.name}`, () => {
    assert.deepEqual(stripRequest(c.request, { sendMessages: true }), c.sent);
  });
}

for (const c of cases.merge) {
  test(`merge: ${c.name}`, () => {
    assert.deepEqual(mergeHealedBody(c.request, c.healed), c.replay);
  });
}

// Whatever the table says, no secret is allowed to appear anywhere in the bytes
// that actually go out — a nesting the table's own expectations got wrong would
// still be caught here.
test('nothing marked SECRET survives the strip, in any case in the table', () => {
  for (const c of cases.strip) {
    const wire = JSON.stringify(stripRequest(c.request));
    for (const secret of ['SECRET', 'THE USERS WHOLE DOCUMENT', 'acme-42', 'user-99',
      'sid-1', 'cache-1', 'MCP_BEARER']) {
      assert.equal(wire.includes(secret), false, `${c.name}: ${secret}`);
    }
  }
});

test('stripRequest copies — the caller\'s own request is never touched', () => {
  const original = {
    model: 'm',
    thinking: { type: 'enabled', budget_tokens: 8000 },
    modalities: ['text'],
  };
  const stripped = stripRequest(original);
  (stripped.thinking as Record<string, unknown>).budget_tokens = 1;
  (stripped.modalities as string[]).push('audio');
  assert.deepEqual(original.thinking, { type: 'enabled', budget_tokens: 8000 });
  assert.deepEqual(original.modalities, ['text']);
});

test('mergeHealedBody mutates neither argument', () => {
  const original = { model: 'a', messages: ['m'], thinking: { type: 'enabled' } };
  const healed = { model: 'b', thinking: { type: 'disabled' } };
  mergeHealedBody(original, healed);
  assert.deepEqual(original, { model: 'a', messages: ['m'], thinking: { type: 'enabled' } });
  assert.deepEqual(healed, { model: 'b', thinking: { type: 'disabled' } });
});

// A polluted prototype is a live transitive-dependency vuln class. The walk
// rebuilds every level from own entries, so an inherited key is not the
// caller's request and does not become part of what travels.
test('an inherited key is neither disclosed nor replayed', () => {
  (Object.prototype as unknown as Record<string, unknown>).temperature = 9;
  try {
    assert.deepEqual(stripRequest({ model: 'm' }), { model: 'm' });
    assert.deepEqual(mergeHealedBody({ model: 'm' }, { model: 'm' }), { model: 'm' });
  } finally {
    delete (Object.prototype as unknown as Record<string, unknown>).temperature;
  }
});

import { afterEach, beforeEach, test } from 'node:test';
import assert from 'node:assert/strict';
import { createGoogleGenerativeAI } from '@ai-sdk/google';
import { generateText } from 'ai';
import { autofix } from '../src/index.ts';

const HEAL_URL = 'http://heal.test';

interface ProviderExchangePayload {
  format: string;
  url: string;
  request: { body: Record<string, unknown>; redactedFields?: string[] };
}

const googleError = () => new Response(JSON.stringify({
  error: { code: 404, message: 'models/gemini-1.0-pro is not found', status: 'NOT_FOUND' },
}), { status: 404 });

const googleSuccess = () => new Response(JSON.stringify({
  candidates: [{ content: { role: 'model', parts: [{ text: 'healed' }] }, finishReason: 'STOP' }],
  usageMetadata: { promptTokenCount: 1, candidatesTokenCount: 1, totalTokenCount: 2 },
}), { status: 200 });

function providerStub(script: Array<() => Response>) {
  const calls: Array<{ url: string; body: Record<string, unknown> }> = [];
  const fn = (async (input: RequestInfo | URL, init?: RequestInit) => {
    calls.push({ url: String(input), body: JSON.parse(init?.body as string) });
    return script[Math.min(calls.length - 1, script.length - 1)]!();
  }) as typeof globalThis.fetch;
  return { fn, calls };
}

const realFetch = globalThis.fetch;
let healCalls: Array<{ body: Record<string, unknown>; headers: Headers }> = [];
let healedBody: Record<string, unknown>;

beforeEach(() => {
  process.env.AUTOFIX_URL = HEAL_URL;
  healCalls = [];
  healedBody = { model: 'gemini-2.5-flash', generationConfig: { temperature: 1 } };
  globalThis.fetch = (async (_input: RequestInfo | URL, init?: RequestInit) => {
    healCalls.push({ body: JSON.parse(init?.body as string), headers: new Headers(init?.headers) });
    return new Response(JSON.stringify({
      status: 'unverified', issueId: 'i1', healAttemptId: 'a1',
      healedBody,
    }), { status: 200 });
  }) as typeof globalThis.fetch;
});

afterEach(() => {
  globalThis.fetch = realFetch;
  delete process.env.AUTOFIX_URL;
});

test('heals @ai-sdk/google GenerateContent and includes contents when opted in', async () => {
  healedBody = { model: 'models/gemini-2.5-flash', generationConfig: { temperature: 1 } };
  const provider = providerStub([googleError, googleSuccess]);
  const google = createGoogleGenerativeAI({
    apiKey: 'provider-secret',
    fetch: autofix({ fetch: provider.fn, sendMessages: true }),
  });
  const result = await generateText({
    model: google('gemini-1.0-pro'),
    prompt: 'private prompt',
    temperature: 0.2,
    maxRetries: 0,
  });

  assert.equal(result.text, 'healed');
  const payload = healCalls[0]!.body;
  assert.equal(payload.provider, 'gemini');
  assert.equal(payload.api, 'chat_completions');
  assert.deepEqual((payload.response as Record<string, unknown>).error, {
    message: 'models/gemini-1.0-pro is not found', type: 'NOT_FOUND', code: '404',
  });
  assert.equal((payload.request as Record<string, unknown>).model, 'gemini-1.0-pro');
  assert.deepEqual(
    (payload.request as Record<string, unknown>).contents,
    provider.calls[0]!.body.contents,
  );
  assert.equal(healCalls[0]!.headers.get('x-autofix-source'), 'vercel-sdk');

  const exchange = payload.providerExchange as ProviderExchangePayload;
  assert.equal(exchange.format, 'google_generate_content');
  assert.equal(exchange.url,
    'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.0-pro:generateContent');
  assert.equal('model' in exchange.request.body, false);
  assert.deepEqual(exchange.request.body.contents, provider.calls[0]!.body.contents);

  assert.match(provider.calls[1]!.url, /models\/gemini-2\.5-flash:generateContent$/);
  assert.equal('model' in provider.calls[1]!.body, false);
  assert.deepEqual(provider.calls[1]!.body.contents, provider.calls[0]!.body.contents);
  assert.equal((provider.calls[1]!.body.generationConfig as Record<string, unknown>).temperature, 1);
});

test('recognizes streaming paths, redacts contents by default, and preserves the query', async () => {
  const provider = providerStub([googleError, googleSuccess]);
  const body = {
    contents: [{ role: 'user', parts: [{ text: 'private prompt' }] }],
    systemInstruction: { parts: [{ text: 'private system' }] },
    generationConfig: { temperature: 0.2 },
  };
  const url = 'https://gateway.test/v1beta/models/gemini-1.0-pro:streamGenerateContent?alt=sse';
  const response = await autofix({ fetch: provider.fn })(url, {
    method: 'POST', body: JSON.stringify(body),
  });

  assert.equal(response.status, 200);
  const payload = healCalls[0]!.body;
  assert.equal(payload.url,
    'https://gateway.test/v1beta/models/gemini-1.0-pro:streamGenerateContent');
  assert.deepEqual(payload.request, {
    model: 'gemini-1.0-pro', generationConfig: { temperature: 0.2 },
  });
  const exchange = payload.providerExchange as ProviderExchangePayload;
  assert.deepEqual(exchange.request.redactedFields, ['contents', 'systemInstruction']);
  assert.match(provider.calls[1]!.url, /streamGenerateContent\?alt=sse$/);
  assert.deepEqual(provider.calls[1]!.body.contents, body.contents);
  assert.deepEqual(provider.calls[1]!.body.systemInstruction, body.systemInstruction);
});

test('a GenerateContent-shaped path without a model still fails open safely', async () => {
  const provider = providerStub([googleError, googleSuccess]);
  const url = 'https://gateway.test/v1beta/gemini:generateContent';
  const body = { contents: [], generationConfig: { temperature: 0.2 } };
  const response = await autofix({ fetch: provider.fn })(url, {
    method: 'POST', body: JSON.stringify(body),
  });

  assert.equal(response.status, 200);
  assert.equal('model' in (healCalls[0]!.body.request as Record<string, unknown>), false);
  assert.equal(provider.calls[1]!.url, url);
  assert.equal('model' in provider.calls[1]!.body, false);
});

test('a malformed encoded model is omitted from the logical request', async () => {
  healedBody = { generationConfig: { temperature: 1 } };
  const provider = providerStub([googleError, googleSuccess]);
  const url = 'https://gateway.test/v1beta/models/%E0%A4%A:generateContent';
  await autofix({ fetch: provider.fn })(url, {
    method: 'POST', body: JSON.stringify({ contents: [] }),
  });
  assert.equal('model' in (healCalls[0]!.body.request as Record<string, unknown>), false);
});

import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { autofix, type HealEvent } from '../src/index.ts';

const ANTHROPIC = 'https://api.anthropic.com/v1/messages';
const HEAL_URL = 'http://heal.test';

// Anthropic's envelope: {"type":"error","error":{"type","message"}} — note it
// carries NO `param` and NO `code`, unlike OpenAI.
const err400 = () => new Response(JSON.stringify({
  type: 'error',
  error: { type: 'invalid_request_error',
    message: 'frequency_penalty: Extra inputs are not permitted' },
}), { status: 400 });

const ok200 = () => new Response(JSON.stringify({ ok: true }), { status: 200 });

// Bodies the wrapper must not touch still reach the provider — record them as
// {} instead of throwing.
const readBody = (body: BodyInit | null | undefined): Record<string, unknown> => {
  try { return JSON.parse(body as string) as Record<string, unknown>; } catch { return {}; }
};

function providerStub(script: Array<() => Response>) {
  const calls: { body: Record<string, unknown>; headers: Record<string, string> }[] = [];
  const fn = (async (_input: unknown, init?: RequestInit) => {
    calls.push({
      body: readBody(init?.body),
      headers: Object.fromEntries(new Headers(init?.headers as HeadersInit | undefined)),
    });
    return script[Math.min(calls.length - 1, script.length - 1)]!();
  }) as typeof globalThis.fetch;
  return { fn, calls };
}

const realFetch = globalThis.fetch;
let healCalls: { url: string; method: string; body: Record<string, unknown> | undefined }[] = [];
let healResponder: (body: unknown, init?: RequestInit) => Response | Promise<Response>;

beforeEach(() => {
  process.env.AUTOFIX_URL = HEAL_URL;
  healCalls = [];
  // frequency_penalty is a scalar, so it travelled, so the server can speak for
  // it: the healed body is the corrected parameter set, and the correction here
  // is that frequency_penalty is not in it. `explanation.operations` is prose
  // for a human and is never acted on.
  healResponder = () => new Response(JSON.stringify({
    status: 'unverified', issueId: 'i1', healAttemptId: 'a1',
    healedBody: { model: 'claude-opus-4-6', max_tokens: 100 },
    explanation: { summary: 'Removed the unsupported parameter "frequency_penalty".',
      operations: [{ type: 'drop_param', detail: 'frequency_penalty' }] },
  }), { status: 200 });
  globalThis.fetch = (async (input: never, init?: RequestInit) => {
    const url = String(input);
    if (url.startsWith(HEAL_URL) || url.includes('autofix.manifest.build')) {
      const body = init?.body ? JSON.parse(init.body as string) : undefined;
      healCalls.push({ url, method: init?.method ?? 'GET', body });
      return healResponder(body, init);
    }
    return realFetch(input, init);
  }) as typeof globalThis.fetch;
});
afterEach(() => {
  globalThis.fetch = realFetch;
  delete process.env.AUTOFIX_URL;
});

const reqInit = (body: Record<string, unknown>): RequestInit => ({
  method: 'POST',
  headers: { 'content-length': '999', 'x-api-key': 'sk-ant-secret', 'anthropic-version': '2023-06-01' },
  body: JSON.stringify(body),
});

const messagesBody = {
  model: 'claude-opus-4-6',
  max_tokens: 100,
  frequency_penalty: 0.5,                        // an OpenAI param, not an Anthropic one → 400
  system: 'SECRET_SYSTEM_PROMPT',                // top-level system prompt
  messages: [{ role: 'user', content: 'SECRET' }],
  tools: [{ name: 't', input_schema: { type: 'object', properties: { q: { type: 'string' } } } }],
};

test('heals a messages call: strips content + system, replays, keeps the key', async () => {
  const provider = providerStub([err400, ok200]);
  const events: HealEvent[] = [];
  const fx = autofix({ fetch: provider.fn, onHeal: (e) => events.push(e) });
  const res = await fx(ANTHROPIC, reqInit(messagesBody));
  assert.equal(res.status, 200);

  const payload = healCalls[0]!.body!;
  const wire = JSON.stringify(payload);
  assert.ok(!wire.includes('SECRET'), 'no message content or system prompt on the wire');
  assert.ok(!wire.includes('input_schema'), 'tool schemas never leave');
  const sent = payload.request as Record<string, unknown>;
  assert.equal('system' in sent, false, 'system prompt stripped');
  assert.equal('messages' in sent, false);
  assert.equal('tools' in sent, false);
  assert.equal(sent.max_tokens, 100, 'settings do travel — that is the whole point');
  assert.equal(sent.frequency_penalty, 0.5,
    'the param that caused the 400 travels too, though no list ever named it');
  assert.equal(payload.provider, 'anthropic');
  assert.equal(payload.api, 'messages');

  const replay = provider.calls[1]!;
  assert.equal('frequency_penalty' in replay.body, false,
    'the healed body simply left it out, and omission is how a param is dropped');
  assert.equal(replay.body.system, 'SECRET_SYSTEM_PROMPT', 'system restored on replay');
  assert.deepEqual(replay.body.messages, messagesBody.messages, 'messages restored on replay');
  assert.deepEqual(replay.body.tools, messagesBody.tools, 'tools restored on replay');
  assert.equal(replay.headers['x-api-key'], 'sk-ant-secret', 'provider key stays on its path');
  assert.equal('content-length' in replay.headers, false, 'stale content-length dropped');

  assert.equal(events[0]!.healStatus, 'unverified');
  assert.equal(events[0]!.replayStatusCode, 200);
  assert.deepEqual(events[0]!.operations,
    [{ type: 'drop_param', detail: 'frequency_penalty' }],
    'the server\'s prose reaches the hook — it is the only account of what changed');
});

// There is one adapter now, so "the adapters do not overlap" is not a property
// this file can state. What replaced it: each path is attributed to the right
// provider/api through the single autofix() — tests/index.test.ts, 'one fetch
// instance routes all four dialects to the right provider' — and paths outside
// the four dialect tails stay inert — same file, 'unknown paths leave the
// universal wrapper inert'. The Anthropic-specific half of that stays here.

test('non-messages Anthropic paths stay inert', async () => {
  const provider = providerStub([err400]);
  const fx = autofix({ fetch: provider.fn });
  const res = await fx('https://api.anthropic.com/v1/complete', reqInit(messagesBody));
  assert.equal(res.status, 400);
  assert.equal(healCalls.length, 0);
});

test('heals through a custom baseURL (gateway/proxy/localhost)', async () => {
  const provider = providerStub([err400, ok200]);
  const fx = autofix({ fetch: provider.fn });
  const res = await fx('https://gw.example.com/v1/messages', reqInit(messagesBody));
  assert.equal(res.status, 200, 'healed and replayed');
  assert.equal(healCalls[0]!.body!.provider, 'anthropic');
  assert.equal('frequency_penalty' in provider.calls[1]!.body, false);
});

test('heal API down → fail open with the original error', async () => {
  healResponder = () => { throw new Error('down'); };
  const provider = providerStub([err400]);
  const events: HealEvent[] = [];
  const fx = autofix({ fetch: provider.fn, onHeal: (e) => events.push(e) });
  const res = await fx(ANTHROPIC, reqInit(messagesBody));
  assert.equal(res.status, 400);
  assert.equal(provider.calls.length, 1, 'no replay happened');
  assert.equal(events[0]!.healStatus, 'heal_unreachable');
});

// ─── the shared engine, seen from the /v1/messages route ────────────────────
// These guarantees live in core/engine.ts, not in either route table. They are
// asserted again here because "it works on OpenAI" is not evidence that the
// adapter a caller actually installed gets them.

test('a hung heal API gives up on its budget on the messages route too', async () => {
  // AbortSignal.timeout's timer is unref'd, so the stub holds the loop open.
  healResponder = (_body, init) => new Promise<Response>((_resolve, reject) => {
    const holdOpen = setTimeout(() => reject(new Error('stub never aborted')), 2000);
    init?.signal?.addEventListener('abort', () => {
      clearTimeout(holdOpen);
      reject(new Error('aborted'));
    });
  });
  const provider = providerStub([err400]);
  const events: HealEvent[] = [];
  const fx = autofix({ fetch: provider.fn, healTimeoutMs: 20, onHeal: (e) => events.push(e) });
  const res = await fx(ANTHROPIC, reqInit(messagesBody));
  assert.equal(res.status, 400, 'the caller gets its own error, not a hang');
  assert.equal(events[0]!.healStatus, 'heal_unreachable');
  assert.equal(provider.calls.length, 1, 'no replay happened');
});

test('a heal answer that is not an object fails open on the messages route', async () => {
  for (const body of ['null', '"patched"', '[{"status":"patched"}]']) {
    healResponder = () => new Response(body, { status: 200 });
    const provider = providerStub([err400]);
    const events: HealEvent[] = [];
    const fx = autofix({ fetch: provider.fn, onHeal: (e) => events.push(e) });
    const res = await fx(ANTHROPIC, reqInit(messagesBody));
    assert.equal(res.status, 400, `${body} was treated as a heal`);
    assert.equal(provider.calls.length, 1, 'no replay happened');
    assert.equal(events[0]!.healStatus, 'heal_unreachable');
  }
});

test('a hook that throws is not allowed to become an outage', async () => {
  const provider = providerStub([err400, ok200]);
  const fx = autofix({ fetch: provider.fn, onHeal: () => { throw new Error('buggy hook'); } });
  const res = await fx(ANTHROPIC, reqInit(messagesBody));
  assert.equal(res.status, 200, 'the caller still gets its healed response');
  assert.equal('frequency_penalty' in provider.calls[1]!.body, false);
});

